// Filtert die Mails des Triggers nochmals auf den erwarteten Absender und baut
// pro Mail den WhatsApp-Text. Der Trigger filtert bereits serverseitig
// (IMAP-Suche FROM) -- diese zweite Pruefung ist bewusst doppelt, weil der
// Text in einem Kanal fuer alle Follower sichtbar ist.
//
// SENDER muss zum FROM-Filter im Trigger-Node passen ("Custom Email Rules").
// Beginnt SENDER mit "@", wird stattdessen die ganze Domain akzeptiert.
const SENDER = 'CHANGE-ME-ABSENDER@example.com';
// Wie viele Zeichen des Mail-Textes mitgeschickt werden. 0 = nur der Betreff.
const MAX_BODY_CHARS = 500;
// Anhaenge (vom Trigger heruntergeladen) an den naechsten Node durchreichen.
// false = Anhaenge komplett ignorieren.
const SEND_ATTACHMENTS = true;
// Trockenlauf: true = alles laeuft wie sonst (Absender pruefen, Text bauen, Anhaenge laden,
// Chromium starten, WhatsApp-Session pruefen), aber am Ende wird NICHTS in den Kanal gesendet.
// Der Node "An WhatsApp senden" liefert dann pro Beitrag ein Item mit dryRun: true.
// Hinweis: Der Trigger markiert die Mail trotzdem als gelesen -- zum Testen besser per
// Pin Data und manuellem Lauf, als eine echte Mail zu verbrauchen.
const TEST = false;

if (SENDER.startsWith('CHANGE-ME')) {
  throw new Error('SENDER im Node "Nachricht bauen" ist noch nicht gesetzt.');
}

// Der Trigger liefert Header-Werte roh, d. h. Umlaute im Betreff kommen als
// RFC-2047-Woerter an (=?UTF-8?Q?...?= / =?UTF-8?B?...?=).
function decodeWords(s) {
  return String(s || '')
    .replace(/(\?=)\s+(=\?)/g, '$1$2')
    .replace(/=\?([^?]+)\?([bBqQ])\?([^?]*)\?=/g, (whole, charset, enc, txt) => {
      try {
        const buf = enc.toUpperCase() === 'B'
          ? Buffer.from(txt, 'base64')
          : Buffer.from(
              txt.replace(/_/g, ' ').replace(/=([0-9A-Fa-f]{2})/g, (m, h) => String.fromCharCode(parseInt(h, 16))),
              'latin1',
            );
        return buf.toString(/^utf-?8$/i.test(charset) ? 'utf8' : 'latin1');
      } catch (e) {
        return whole;
      }
    })
    .trim();
}

function addressOf(from) {
  const s = String(from || '');
  const m = s.match(/<([^>]+)>/);
  return (m ? m[1] : s).trim().toLowerCase();
}

function senderMatches(from) {
  const addr = addressOf(from);
  const want = SENDER.toLowerCase();
  return want.startsWith('@') ? addr.endsWith(want) : addr === want;
}

// Der Trigger dekodiert Quoted-Printable-Teile nur dann als UTF-8, wenn der Zeichensatz exakt
// "UTF-8" lautet; fehlt er oder steht "utf8" da, kommen die UTF-8-Bytes als Latin-1-Zeichen an
// ("GrÃ¼Ãen"). Das ist verlustfrei umkehrbar, solange alle Zeichen <= U+00FF sind und die
// Bytes gueltiges UTF-8 ergeben. Echtes Latin-1 ("Grüßen") ergibt kein gueltiges UTF-8 und
// bleibt unveraendert.
function repairMojibake(s) {
  const str = String(s || '');
  if (!/[\u0080-\u00FF]/.test(str) || /[^\u0000-\u00FF]/.test(str)) return str;
  const fixed = Buffer.from(str, 'latin1').toString('utf8');
  return fixed.includes('\uFFFD') ? str : fixed;
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>|<\/(p|div|tr|li|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&');
}

function bodyExcerpt(json) {
  if (MAX_BODY_CHARS <= 0) return '';
  const plain = repairMojibake(json.textPlain);
  const raw = plain.trim() ? plain : htmlToText(repairMojibake(json.textHtml));
  const clean = raw.replace(/\r/g, '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
  const chars = Array.from(clean);
  return chars.length > MAX_BODY_CHARS ? chars.slice(0, MAX_BODY_CHARS).join('').trimEnd() + '…' : clean;
}

const all = $input.all();
const out = [];
for (const item of all) {
  const j = item.json;
  if (!senderMatches(j.from)) continue;
  const subject = decodeWords(j.subject) || '(kein Betreff)';
  const body = bodyExcerpt(j);
  const text = '\u{1F4E7} *' + subject + '*' + (body ? '\n\n' + body : '');
  // Der Trigger legt Anhaenge als Binaerfelder attachment_0, attachment_1, ... ab.
  const attachments = SEND_ATTACHMENTS
    ? Object.entries(item.binary || {}).map(([key, b]) => ({ key, fileName: b.fileName || key, mimeType: b.mimeType || '' }))
    : [];
  const result = { json: { text, subject, from: decodeWords(j.from), attachments } };
  if (TEST === true) result.json.test = true;
  if (attachments.length) result.binary = item.binary;
  out.push(result);
}

// Kam etwas vom Trigger, aber nichts passt zu SENDER, stimmen Trigger-Filter
// und SENDER nicht ueberein -> lautstark scheitern statt still zu verwerfen.
if (all.length && !out.length) {
  throw new Error('Trigger lieferte ' + all.length + ' Mail(s), aber keine passt zu SENDER "' + SENDER
    + '" (Absender z. B.: ' + decodeWords(all[0].json.from) + '). FROM-Filter im Trigger und SENDER angleichen.');
}
return out;

// Sendet die Texte (und Anhaenge) aus "Nachricht bauen" in EINEN WhatsApp-Kanal (TARGET_ID).
// Chats und Gruppen sind bewusst gesperrt: TARGET_ID muss "<Ziffern>@newsletter" sein, das wird
// hier UND im Kindprozess geprueft, und das Ziel kommt nie aus den Mail-Daten.
//
// Warum ein Kindprozess: Der n8n-Task-Runner friert alle globalen Prototypen ein (u. a.
// Error.prototype). Puppeteer (Chromium-Steuerung in whatsapp-web.js) scheitert darin schon
// beim Anlegen seiner Fehlerklassen ("Cannot assign to read only property 'name' ...").
// Deshalb startet dieser Node einen normalen Node.js-Prozess (Funktion waChild unten, per
// stdin mit den Daten gefuettert), der Chromium startet, die gekoppelte Session
// (LocalAuth, liegt auf dem n8n-PVC) wiederherstellt, sendet und alles wieder beendet.
// Einmalige Kopplung + Ziel-ID ermitteln: scripts/whatsapp-pair.js
// (Anleitung: docs/3-apps-workloads/30070-n8n.md, Abschnitt "E-Mail -> WhatsApp-Kanal").
//
// Braucht in values.yaml: NODE_FUNCTION_ALLOW_BUILTIN=child_process.
const { spawn } = require('child_process');

// Nur Kanaele: 1234567890@newsletter
const TARGET_ID = 'CHANGE-ME@newsletter';

const NODE_BIN = '/usr/local/bin/node';
const CHILD_ENV = { PATH: '/usr/local/bin:/usr/bin:/bin', HOME: '/home/node', NODE_PATH: '/opt/wwebjs/node_modules' };
const CONFIG = {
  targetId: TARGET_ID,
  authDir: '/home/node/.n8n/whatsapp-session',
  lockDir: '/home/node/.n8n/whatsapp-session.lock',
  chromium: '/usr/bin/chromium-browser',
  readyTimeoutMs: 90000,   // Chromium + WhatsApp Web laden
  sendTimeoutMs: 45000,    // pro Textnachricht
  mediaTimeoutMs: 90000,   // pro Anhang (Upload)
  pauseMs: 4000,           // zwischen zwei Nachrichten
  settleMs: 3000,          // nach dem letzten Senden, bevor Chromium beendet wird
  lockWaitMs: 120000,      // so lange auf einen parallelen Versand warten
  lockStaleMs: 310000,     // n8n bricht Code-Tasks nach 300 s ab -> aelteres Lock ist tot
  budgetMs: 240000,        // Zeitbudget fuer das Senden; danach Abbruch mit Fehler
  watchdogMs: 270000,      // harte Grenze im Kindprozess (beendet Chromium und sich selbst)
  dryRun: false,           // wird unten aus dem Flag TEST im Node "Nachricht bauen" gesetzt
};
const KILL_AFTER_MS = 285000; // harte Grenze im Elternprozess, muss unter den 300 s des Runners bleiben

// Anhaenge: Kanaele nehmen laut whatsapp-web.js nur Bilder und MP4-Videos an, bei Medien
// gilt ca. 16 MB als Grenze. Alles andere wird im Text namentlich erwaehnt.
const MAX_ATTACHMENT_BYTES = 15 * 1024 * 1024;
const MAX_ATTACHMENTS_PER_MAIL = 3;
const CHANNEL_MIME = /^(image\/(jpeg|png|gif|webp)|video\/mp4)$/i;

if (TARGET_ID.startsWith('CHANGE-ME')) {
  throw new Error('TARGET_ID im Node "An WhatsApp senden" ist noch nicht gesetzt.');
}
if (!/^\d+@newsletter$/.test(TARGET_ID)) {
  throw new Error('TARGET_ID muss ein WhatsApp-Kanal sein (Ziffern@newsletter). Chats und Gruppen sind gesperrt.');
}

// ---- Laeuft im Kindprozess (normales Node.js, kein Runner-Sandbox) --------------------------
function waChild() {
  const fs = require('fs');

  // Zwei Workarounds fuer whatsapp-web.js 1.34.7 beim Senden von MEDIEN (Text ist nicht betroffen).
  // Beide werden in die Injektions-Funktion LoadUtils eingefuegt, BEVOR die Bibliothek sie
  // einliest, und entfallen von selbst, sobald eine neue Version die Stellen selbst behebt.
  //  1) WhatsApp Web >= 2.3000.1047775310 (Issues wwebjs/whatsapp-web.js#201921/#201922):
  //     das interne "__x_id" des Medien-Modells landet in der Nachricht und ueberschreibt deren
  //     ID -> "Data passed to getter must include an id property (it's how we memoize)".
  //     Fix: die Zeile "delete message.__x_id;".
  //  2) WhatsApp Web hat Msg.avParams() entfernt (Issue #201823, PR #201824) -> "msg.avParams is
  //     not a function" beim Senden in Kanaele. Ersatz: WAWebMediaMetadata.mediaMetadata(msg).
  //     Beides gegen WhatsApp Web 2.3000.1048563346 geprueft (Modul vorhanden, avParams fehlt).
  function patchMediaSend() {
    const utils = require('whatsapp-web.js/src/util/Injected/Utils');
    const original = utils.LoadUtils.toString();
    let src = original;
    const marker = "// Bot's won't reply if canonicalUrl is set (linking)";
    if (!src.includes('delete message.__x_id') && src.includes(marker)) {
      src = src.replace(marker, 'delete message.__x_id;\n        ' + marker);
    }
    const oldCall = 'mediaMetadata: msg.avParams(),';
    if (src.includes(oldCall)) {
      src = src.replace(oldCall, "mediaMetadata: typeof msg.avParams === 'function' ? msg.avParams() : window.require('WAWebMediaMetadata').mediaMetadata(msg),");
    }
    if (src !== original) utils.LoadUtils = (0, eval)('(' + src + ')');
  }
  patchMediaSend();
  const { Client, LocalAuth, MessageMedia } = require('whatsapp-web.js');

  let cfg;
  let client = null;
  let lockHeld = false;

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const withTimeout = (promise, ms, message) => {
    let timer;
    const timeout = new Promise((resolve, reject) => { timer = setTimeout(() => reject(new Error(message)), ms); });
    return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
  };
  const finish = (obj, code) => process.stdout.write(JSON.stringify(obj) + '\n', () => process.exit(code));

  // Chromium darf ein Profil nur einmal oeffnen -> parallele Ausfuehrungen (zwei Mails kurz
  // hintereinander) muessen nacheinander laufen.
  async function acquireLock() {
    const deadline = Date.now() + cfg.lockWaitMs;
    for (;;) {
      try {
        fs.mkdirSync(cfg.lockDir);
        lockHeld = true;
        return;
      } catch (e) {
        if (e.code !== 'EEXIST') throw e;
        let age;
        try { age = Date.now() - fs.statSync(cfg.lockDir).mtimeMs; } catch (e2) { continue; }
        if (age > cfg.lockStaleMs) { fs.rmSync(cfg.lockDir, { recursive: true, force: true }); continue; }
        if (Date.now() > deadline) throw new Error('Ein anderer WhatsApp-Versand laeuft noch (Lock ' + cfg.lockDir + ').');
        await sleep(3000);
      }
    }
  }

  // Nach einem Pod-Neustart mitten im Versand bleiben Chromium-Lockdateien mit dem alten
  // Hostnamen liegen; Chromium startet dann nicht ("profile in use").
  function removeChromiumLocks() {
    for (const f of ['SingletonLock', 'SingletonCookie', 'SingletonSocket']) {
      try { fs.rmSync(cfg.authDir + '/session/' + f, { force: true }); } catch (e) { /* nicht vorhanden */ }
    }
  }

  async function cleanup() {
    if (client) {
      try {
        await withTimeout(client.destroy(), 20000, 'destroy() haengt.');
      } catch (e) {
        try { client.pupBrowser.process().kill('SIGKILL'); } catch (e2) { /* Browser schon weg */ }
      }
      client = null;
    }
    if (lockHeld) {
      try { fs.rmSync(cfg.lockDir, { recursive: true, force: true }); } catch (e) { /* egal */ }
      lockHeld = false;
    }
  }

  async function send(input) {
    if (!/^\d+@newsletter$/.test(cfg.targetId)) throw new Error('Ziel ist kein Kanal: ' + cfg.targetId);
    const t0 = Date.now();
    const results = [];

    await acquireLock();
    removeChromiumLocks();
    client = new Client({
      authStrategy: new LocalAuth({ dataPath: cfg.authDir }),
      puppeteer: {
        headless: true,
        executablePath: cfg.chromium,
        args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--disable-gpu', '--no-first-run'],
      },
    });

    const ready = new Promise((resolve, reject) => {
      client.once('ready', resolve);
      client.once('qr', () => reject(new Error('WhatsApp-Session nicht (mehr) gekoppelt (QR-Code angefordert). Neu koppeln: scripts/whatsapp-pair.js')));
      client.once('auth_failure', (m) => reject(new Error('WhatsApp-Anmeldung fehlgeschlagen: ' + m)));
      client.once('disconnected', (r) => reject(new Error('WhatsApp-Verbindung getrennt: ' + r)));
    });
    ready.catch(() => {});
    const init = client.initialize();
    init.catch(() => {});
    await withTimeout(Promise.race([ready, init.then(() => ready)]), cfg.readyTimeoutMs, 'WhatsApp Web wurde nicht rechtzeitig bereit (' + cfg.readyTimeoutMs / 1000 + ' s).');

    // Scheitert ein Text, wird abgebrochen. Scheitert ein Anhang, ist der Text schon raus:
    // die uebrigen Anhaenge werden trotzdem versucht und die Fehler am Ende gemeldet.
    const failures = [];
    const posts = input.posts;
    for (let i = 0; i < posts.length; i++) {
      if (Date.now() - t0 > cfg.budgetMs) {
        throw new Error('Zeitbudget erschoepft: ' + results.length + ' von ' + posts.length + ' Nachricht(en) gesendet.');
      }
      const p = posts[i];
      try {
        if (cfg.dryRun) {
          // Trockenlauf (TEST in "Nachricht bauen"): alles bis hierhin lief echt, gesendet wird nichts.
          results.push({
            sent: false, dryRun: true, kind: p.kind, target: cfg.targetId, subject: p.subject,
            text: p.kind === 'text' ? p.text : undefined,
            file: p.kind === 'media' ? p.fileName : undefined,
            bytes: p.kind === 'media' ? Math.floor(p.data.length * 3 / 4) - (p.data.endsWith('==') ? 2 : p.data.endsWith('=') ? 1 : 0) : undefined,
          });
          continue;
        }
        let msg;
        if (p.kind === 'text') {
          msg = await withTimeout(
            client.sendMessage(cfg.targetId, p.text, { sendSeen: false, linkPreview: false }),
            cfg.sendTimeoutMs,
            'Senden an ' + cfg.targetId + ' dauerte zu lange.',
          );
        } else {
          const media = new MessageMedia(p.mime, p.data, p.fileName);
          msg = await withTimeout(
            client.sendMessage(cfg.targetId, media, { sendSeen: false }),
            cfg.mediaTimeoutMs,
            'Senden des Anhangs ' + p.fileName + ' dauerte zu lange.',
          );
        }
        results.push({ sent: true, kind: p.kind, target: cfg.targetId, messageId: (msg && msg.id && msg.id._serialized) || null, subject: p.subject, file: p.kind === 'media' ? p.fileName : undefined });
      } catch (e) {
        if (p.kind === 'text') throw e;
        failures.push(p.fileName + ': ' + String((e && e.message) || e));
      }
      if (i < posts.length - 1) await sleep(cfg.pauseMs);
    }
    if (!cfg.dryRun) await sleep(cfg.settleMs);
    return { results, failures };
  }

  let raw = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => { raw += chunk; });
  process.stdin.on('end', async () => {
    let input;
    try {
      input = JSON.parse(raw);
      cfg = input.config;
    } catch (e) {
      finish({ ok: false, error: 'Kindprozess: Eingabe nicht lesbar: ' + e.message }, 1);
      return;
    }
    setTimeout(() => {
      try { client.pupBrowser.process().kill('SIGKILL'); } catch (e) { /* egal */ }
      try { fs.rmSync(cfg.lockDir, { recursive: true, force: true }); } catch (e) { /* egal */ }
      finish({ ok: false, error: 'Watchdog: Kindprozess nach ' + cfg.watchdogMs / 1000 + ' s abgebrochen.' }, 3);
    }, cfg.watchdogMs);

    let outcome;
    let code = 0;
    try {
      outcome = Object.assign({ ok: true }, await send(input));
    } catch (e) {
      outcome = { ok: false, error: String((e && e.message) || e) };
      code = 1;
    }
    await cleanup();
    finish(outcome, code);
  });
}
// ---------------------------------------------------------------------------------------------

// Base64-Inhalt eines Anhangs. Im Binary-Modus "default" steckt er direkt im Item, im Modus
// "filesystem" liegt nur eine Referenz (id) im Item und der Runner muss die Datei ueber
// helpers nachladen.
async function attachmentBase64(items, i, key) {
  const b = items[i].binary[key];
  if (b.data && !b.id) return b.data;
  return Buffer.from(await helpers.getBinaryDataBuffer(i, key)).toString('base64');
}

// Baut je Mail die Beitraege: erst der Text (mit Hinweis auf nicht uebertragene Anhaenge), dann
// jeder Anhang einzeln. Zu grosse/unpassende Anhaenge werden hier aussortiert.
async function buildPosts(items) {
  const posts = [];
  for (let i = 0; i < items.length; i++) {
    const j = items[i].json;
    const media = [];
    const skipped = [];
    for (const a of j.attachments || []) {
      const mime = String(a.mimeType || '').toLowerCase();
      if (media.length >= MAX_ATTACHMENTS_PER_MAIL) { skipped.push(a.fileName + ' (zu viele Anhänge)'); continue; }
      if (!CHANNEL_MIME.test(mime)) { skipped.push(a.fileName + ' (Dateityp im Kanal nicht möglich)'); continue; }
      const data = await attachmentBase64(items, i, a.key);
      if (Math.floor(data.length * 3 / 4) > MAX_ATTACHMENT_BYTES) { skipped.push(a.fileName + ' (zu groß)'); continue; }
      media.push({ kind: 'media', mime, data, fileName: a.fileName, subject: j.subject });
    }
    const note = skipped.length ? '\n\n\u{1F4CE} Nicht übertragen: ' + skipped.join(', ') : '';
    posts.push({ kind: 'text', text: j.text + note, subject: j.subject });
    posts.push(...media);
  }
  return posts;
}

function runChild(payload) {
  return new Promise((resolve, reject) => {
    const child = spawn(NODE_BIN, ['-e', '(' + waChild.toString() + ')()'], { env: CHILD_ENV, stdio: ['pipe', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    child.stdout.setEncoding('utf8');
    child.stderr.setEncoding('utf8');
    child.stdout.on('data', (d) => { out += d; });
    child.stderr.on('data', (d) => { err = (err + d).slice(-4000); });
    const killer = setTimeout(() => child.kill('SIGKILL'), KILL_AFTER_MS);
    child.on('error', (e) => { clearTimeout(killer); reject(new Error('Kindprozess nicht startbar: ' + e.message)); });
    child.on('close', (code) => {
      clearTimeout(killer);
      const last = out.trim().split('\n').filter(Boolean).pop();
      let res = null;
      try { res = JSON.parse(last); } catch (e) { /* keine gueltige Antwort */ }
      if (res && res.ok) { resolve(res); return; }
      const detail = err.trim().split('\n').slice(-3).join(' | ');
      reject(new Error(res ? res.error : 'WhatsApp-Prozess endete mit Code ' + code + (detail ? ': ' + detail : '')));
    });
    child.stdin.on('error', () => { /* Kind vorzeitig beendet; close meldet den Grund */ });
    child.stdin.end(JSON.stringify(payload));
  });
}

const items = $input.all();
if (!items.length) return [];
const posts = await buildPosts(items);
// TEST = true in "Nachricht bauen" -> Trockenlauf (alles ausser dem eigentlichen Senden)
const dryRun = items.some((it) => it.json.test === true);
const { results, failures } = await runChild({ config: Object.assign({}, CONFIG, { dryRun }), posts });
if (failures && failures.length) {
  throw new Error('Text gesendet, aber ' + failures.length + ' Anhang/Anhänge fehlgeschlagen: ' + failures.join(' | '));
}
return results.map((r) => ({ json: r }));

// Wird ueber den Fehler-Ausgang von "Nachricht bauen" bzw. "An WhatsApp senden"
// erreicht. Die Mail ist zu diesem Zeitpunkt im Postfach schon als gelesen
// markiert, daher kommt der geplante WhatsApp-Text per ntfy als Rueckfall mit.
const first = $input.first().json;
const err = first && first.error;
const reason = (typeof err === 'string' ? err : err && (err.message || err.description)) || JSON.stringify(first);

let geplant = '';
try {
  geplant = $('Nachricht bauen').all().map((i) => i.json.text).join('\n\n---\n\n');
} catch (e) { /* Fehler trat schon in "Nachricht bauen" auf */ }

const body = 'Fehler: ' + reason + '\n\n' + (geplant
  ? 'Geplanter WhatsApp-Text (Mail ist im Postfach als gelesen markiert; falls schon teilweise gesendet, steht es in der Fehlermeldung):\n\n' + geplant
  : 'Die Mail(s) sind im Postfach als gelesen markiert -- bitte dort nachsehen.');
return [{ json: { body } }];
